<?php
require __DIR__ . '/functions.php'; $lang=current_lang(); $action=$_GET['action']??'';
if($action==='add'||$action==='minus'){ $id=(int)($_GET['id']??0); set_cart_quantity($id,(int)($_SESSION['cart'][$id]??0)+($action==='add'?1:-1)); header('Location:index.php?view=cart&lang='.$lang); exit; }
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['product_id']??0);if(($_POST['action']??'')==='add')add_to_cart($id,(int)($_POST['quantity']??1));if(($_POST['action']??'')==='remove')remove_from_cart($id);header('Location:index.php?view=cart&lang='.$lang);exit;}
$view=$_GET['view']??'shop';$category=$_GET['category']??'';$q=$_GET['q']??'';$s=db()->prepare('SELECT * FROM products WHERE active=1 AND (?="" OR category=?) AND (name LIKE ? OR description LIKE ?) ORDER BY id DESC');$like="%$q%";$s->execute([$category,$category,$like,$like]);$products=$s->fetchAll();$lines=cart_products();$subtotal=array_reduce($lines,fn($sum,$line)=>$sum+$line['price']*$line['quantity'],0);
function art(array $p):string{$content=!empty($p['image_path'])?'<img src="'.e($p['image_path']).'" alt="'.e($p['name']).'">':'<strong>'.e($p['short_name']).'</strong><small>'.e($p['color']).'</small>';return '<div class="art" style="background:'.e($p['image_color']).'">'.$content.'</div>';}
?><!doctype html><html lang="<?= $lang ?>" dir="<?= $lang==='ar'?'rtl':'ltr' ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lissi | <?= text('shop') ?></title><link rel="stylesheet" href="style.css"></head><body class="<?= $view==='cart'?'cart-page':'' ?>"><header class="header shell"><a class="brand" href="index.php"><img src="assets/logo.jpeg" alt="Lissi"><span>LISSI</span></a><nav class="nav"><a href="index.php?lang=<?= $lang ?>"><?= text('shop') ?></a><a href="?category=Women&lang=<?= $lang ?>"><?= text('women') ?></a><a href="?category=Men&lang=<?= $lang ?>"><?= text('men') ?></a><a href="?category=Accessories&lang=<?= $lang ?>"><?= text('accessories') ?></a></nav><div class="header-tools"><a class="bag" href="?view=cart&lang=<?= $lang ?>"><?= text('bag') ?> (<?= cart_count() ?>)</a><a href="?lang=ar">ع</a><a href="?lang=fr">FR</a><a href="?lang=en">EN</a><button class="theme-toggle" type="button" data-theme-toggle>Theme</button></div></header><?php if($view==='cart'): ?><section class="section shell"><p class="eyebrow"><?= text('bag') ?></p><h2><?= text('bag') ?></h2><?php if(!$lines): ?><p><?= $lang==='ar'?'السلة فارغة حالياً.':'Your bag is empty.' ?></p><?php else: foreach($lines as $line): ?><div class="line"><?= art($line) ?><div><b><?= e($line['name']) ?></b><span><?= money($line['price']) ?></span><div class="step"><a href="?view=cart&action=minus&id=<?= $line['id'] ?>&lang=<?= $lang ?>">−</a><span><?= $line['quantity'] ?></span><a href="?view=cart&action=add&id=<?= $line['id'] ?>&lang=<?= $lang ?>">+</a><form method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= $line['id'] ?>"><button type="submit">×</button></form></div></div></div><?php endforeach; ?><div class="summary"><div><span>Subtotal</span><b><?= money($subtotal) ?></b></div><div class="total"><span>Total</span><b><?= money($subtotal) ?></b></div><p class="muted"><?= $lang==='ar'?'سيتم حساب التوصيل بعد اختيار الطريقة.':'Delivery is calculated after you choose a method.' ?></p><a class="dark" href="checkout.php?lang=<?= $lang ?>"><?= text('checkout') ?> →</a></div><?php endif; ?></section><?php else: ?><section class="hero shell"><div class="hero-copy"><p class="eyebrow">The everyday edit / 01</p><h1><?= $lang==='ar'?'اختيارات جميلة<br><em>ليومك العادي</em>':'Good things,<br><em>beautifully</em> chosen.' ?></h1><p><?= $lang==='ar'?'قطع مختارة بعناية، سهلة الحب ومصممة لتدوم.':'Thoughtful pieces for the way you live now. Easy to love, made to last.' ?></p><a class="dark" href="#catalog"><?= text('find') ?> ↓</a></div><div class="hero-art"></div></section><section id="catalog" class="section shell"><div class="section-head"><div><p class="eyebrow"><?= $lang==='ar'?'وصل حديثاً':'Just in' ?></p><h2><?= text('find') ?></h2></div><div class="filters"><a href="?lang=<?= $lang ?>"><?= text('all') ?></a><a href="?category=Women&lang=<?= $lang ?>"><?= text('women') ?></a><a href="?category=Men&lang=<?= $lang ?>"><?= text('men') ?></a><a href="?category=Accessories&lang=<?= $lang ?>"><?= text('accessories') ?></a></div></div><div class="grid"><?php foreach($products as $p): ?><article class="card"><form method="post"><?= art($p) ?><div class="meta"><div><b><?= e($p['name']) ?></b><span><?= e($p['category']) ?> · <?= e($p['sizes']) ?></span></div><b><?= money($p['price']) ?></b></div><div class="stock"><i></i><?= $p['stock']<5?'Only '.$p['stock'].' left':'In stock' ?></div><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><button class="dark" type="submit"><?= text('add') ?> +</button></form></article><?php endforeach; ?></div></section><?php endif; ?><footer class="footer shell"><div><b>LISSI</b><p>Little things, thoughtfully chosen.</p></div><div><b>hello@lissi.dz</b></div></footer><script>const t=document.querySelector('[data-theme-toggle]'),saved=localStorage.getItem('lissi-theme');if(saved)document.documentElement.dataset.theme=saved;t?.addEventListener('click',()=>{const n=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=n;localStorage.setItem('lissi-theme',n)});</script></body></html>
